#!/bin/bash
# Build 25: upstream nx2 d2eaae4f (#1143 evicted pipeline pointers, shader cache v2) with the
# unbacked image fix, #313 ported to shader cache v2, 128 query banks and PR #1023.
set -eux
UP=${UPSTREAM:-https://github.com/zortos293/lichii}
if [ -z "${LOCAL_ONLY:-}" ]; then
  git fetch -q "$UP" d2eaae4f3abca636b030b726f107bace06f61079
fi
git checkout -q --detach d2eaae4f3abca636b030b726f107bace06f61079
echo "" | base64 -d | xz -d > "${RUNNER_TEMP:-/tmp}/b25.diff"
git apply --index "${RUNNER_TEMP:-/tmp}/b25.diff"
git commit -q -m "Build 25 changes: unbacked image fix (e15125b), #313 on shader cache v2, 128 query banks, PR #1023"
test "$(git rev-parse 'HEAD^{tree}')" = 2fe82b2aba028bb6b687871c34d4b9427e2c49b7
for f in $(git ls-tree -r --name-only HEAD .github); do
  git cat-file -e "fork_tip:$f" 2>/dev/null || git rm -q "$f"
done
git checkout fork_tip -- .github
git commit -q -m "Keep this fork's workflow files" || true
test -z "$(git diff fork_tip HEAD -- .github)"
TREE=$(git rev-parse 'HEAD^{tree}')
echo "final tree $TREE"
NEW=$(git commit-tree "$TREE" -p fork_tip -p HEAD -m "Build 25: upstream nx2 d2eaae4f (#1143 white light fix, shader cache v2) with the unbacked image fix, #313, 128 query banks and #1023")
git checkout -q --detach "$NEW"
